{
 "content": "import json
import os
import urllib.request
import urllib.error

def send_prompt(prompt: str, model: str = "gpt-4o") -> str:
    """
    Sends a text prompt to OpenAI's Chat Completions API using only the standard library.

    Args:
        prompt: The text prompt to send.
        model: The model to use (default: gpt-4o).

    Returns:
        The text response from the API.
    """
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("OPENAI_API_KEY environment variable is not set.")

    url = "https://api.openai.com/v1/chat/completions"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {api_key}"
    }

    data = {
        "model": model,
        "messages": [
            {"role": "user", "content": prompt}
        ]
    }

    req = urllib.request.Request(
        url,
        data=json.dumps(data).encode("utf-8"),
        headers=headers,
        method="POST"
    )

    try:
        with urllib.request.urlopen(req) as response:
            response_body = response.read().decode("utf-8")
            response_json = json.loads(response_body)
            return response_json["choices"][0]["message"]["content"]
    except urllib.error.HTTPError as e:
        error_info = e.read().decode("utf-8")
        raise RuntimeError(f"HTTPError {e.code}: {e.reason} - {error_info}") from e
    except urllib.error.URLError as e:
        raise RuntimeError(f"URLError: {e.reason}") from e

if __name__ == "__main__":
    # Example usage
    try:
        response = send_prompt("Say hello world!")
        print("Response:", response)
    except Exception as e:
        print("Error:", e)
